 "content": "def transform(grid):
    """Connect every pair of marked cells sharing a row or column."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = max(counts, key=counts.get)
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != background}
    out = [row[:] for row in grid]
    for r1, c1 in markers:
        for r2, c2 in markers:
            if r1 == r2 and c1 < c2:
                for c in range(c1 + 1, c2):
                    out[r1][c] = 3
            elif c1 == c2 and r1 < r2:
                for r in range(r1 + 1, r2):
                    out[r][c1] = 3
    return out
